CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE POLICY "Own profile create" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('editor');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, PRIMARY KEY (user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own role read" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_exhibition_editor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'editor'); $$;
REVOKE ALL ON FUNCTION public.is_exhibition_editor() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_exhibition_editor() TO authenticated;
CREATE FUNCTION public.setup_reviewer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING; IF lower(NEW.email) = 'bdft@hotmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'editor') ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id = NEW.id AND role = 'editor'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.setup_reviewer() FROM PUBLIC;
CREATE TRIGGER setup_reviewer_after_auth AFTER INSERT OR UPDATE OF email, email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.setup_reviewer();
CREATE TABLE public.exhibitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_date date NOT NULL, event_es text NOT NULL, event_en text NOT NULL, dog_name text NOT NULL, results_es text NOT NULL, results_en text NOT NULL, award_es text NOT NULL DEFAULT '', award_en text NOT NULL DEFAULT '', judge_es text NOT NULL, judge_en text NOT NULL, image_url text NOT NULL DEFAULT '', source_url text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.exhibitions TO anon;
GRANT SELECT, INSERT, UPDATE ON public.exhibitions TO authenticated;
GRANT ALL ON public.exhibitions TO service_role;
ALTER TABLE public.exhibitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Approved public exhibitions" ON public.exhibitions FOR SELECT TO anon, authenticated USING (status = 'approved');
CREATE POLICY "Editors read all exhibitions" ON public.exhibitions FOR SELECT TO authenticated USING (public.is_exhibition_editor());
CREATE POLICY "Editors insert exhibitions" ON public.exhibitions FOR INSERT TO authenticated WITH CHECK (public.is_exhibition_editor());
CREATE POLICY "Editors update exhibitions" ON public.exhibitions FOR UPDATE TO authenticated USING (public.is_exhibition_editor()) WITH CHECK (public.is_exhibition_editor());